INSERT INTO `articles` (`id`, `slug`, `title`, `excerpt`, `category`, `subcategory`, `date`, `read_time`, `image`, `featured`, `trending_rank`, `author_name`, `author_avatar`, `author_role`, `quote`, `tags_json`, `content_json`, `views_count`, `likes_count`, `published`, `created_at`, `updated_at`, `html_content`, `focus_keyword`, `meta_title`, `meta_description`, `canonical_url`, `no_index`, `og_image`, `seo_score`, `readability_score`, `has_affiliate_links`, `affiliate_disclosure_custom`) VALUES ('amalfi-coast-guide', 'the-ultimate-amalfi-coast-travel-guide', 'The Ultimate Amalfi Coast Travel Guide', 'Discover the best towns, things to do, where to stay and tips for an unforgettable trip to Italy\'s stunning coastline.', 'Travel', 'Island Escapes', 'May 14, 2026', '8 min read', 'https://images.unsplash.com/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1600&q=80', 1, NULL, 'Toufiq Motion', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=300&q=80', 'Founder & Travel Photographer', 'The Amalfi Coast is not merely a destination; it is an intoxicating feeling of warm stone, salted breezes, and endless lemon groves.', '[\"Italy\",\"Coast\",\"Europe\",\"Summer\",\"Photography\"]', '[\"Clinging dramatically to the rugged cliffs of southern Italy, the Amalfi Coast has captured the imagination of wanderers, artists, and poets for centuries. With pastel-hued villages tumbling into turquoise waters, fragrant lemon groves perched on terraced hillsides, and winding coastal roads offering breathtaking panoramas at every turn, it is undeniably one of Europe’s most magical destinations.\",\"Whether you are dreaming of wandering the chic vertical alleyways of Positano, savoring fresh seafood overlooking the sea in Amalfi, or finding peaceful solitude amid the aristocratic gardens of Ravello, this comprehensive guide will help you experience the very best of this iconic coastline.\",\"Getting Around: While renting a vintage Vespa might seem romantic, during high season the cliffside roads can be challenging. We recommend utilizing the ferry network connecting Salerno, Amalfi, and Positano for the most picturesque perspectives.\",\"Where to Stay: Base yourself in Amalfi for easy transit hub access, or opt for Praiano if you desire peaceful sunsets away from tourist crowds.\"]', 560, 58, 1, '2026-10-30 21:07:30', '2026-10-30 21:07:30', NULL, NULL, NULL, NULL, NULL, 0, NULL, 85, 90, 1, NULL) ON DUPLICATE KEY UPDATE `slug` = VALUES(`slug`), `title` = VALUES(`title`), `excerpt` = VALUES(`excerpt`), `category` = VALUES(`category`), `subcategory` = VALUES(`subcategory`), `date` = VALUES(`date`), `read_time` = VALUES(`read_time`), `image` = VALUES(`image`), `featured` = VALUES(`featured`), `trending_rank` = VALUES(`trending_rank`), `author_name` = VALUES(`author_name`), `author_avatar` = VALUES(`author_avatar`), `author_role` = VALUES(`author_role`), `quote` = VALUES(`quote`), `tags_json` = VALUES(`tags_json`), `content_json` = VALUES(`content_json`), `views_count` = VALUES(`views_count`), `likes_count` = VALUES(`likes_count`), `published` = VALUES(`published`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`), `html_content` = VALUES(`html_content`), `focus_keyword` = VALUES(`focus_keyword`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `canonical_url` = VALUES(`canonical_url`), `no_index` = VALUES(`no_index`), `og_image` = VALUES(`og_image`), `seo_score` = VALUES(`seo_score`), `readability_score` = VALUES(`readability_score`), `has_affiliate_links` = VALUES(`has_affiliate_links`), `affiliate_disclosure_custom` = VALUES(`affiliate_disclosure_custom`);
INSERT INTO `articles` (`id`, `slug`, `title`, `excerpt`, `category`, `subcategory`, `date`, `read_time`, `image`, `featured`, `trending_rank`, `author_name`, `author_avatar`, `author_role`, `quote`, `tags_json`, `content_json`, `views_count`, `likes_count`, `published`, `created_at`, `updated_at`, `html_content`, `focus_keyword`, `meta_title`, `meta_description`, `canonical_url`, `no_index`, `og_image`, `seo_score`, `readability_score`, `has_affiliate_links`, `affiliate_disclosure_custom`) VALUES ('swiss-alps-weekend', 'a-perfect-weekend-in-the-swiss-alps', 'A Perfect Weekend in the Swiss Alps', 'Escape to dramatic peaks, crystal-clear alpine lakes and cozy chalets for a restorative weekend surrounded by nature.', 'Travel', 'Nature & Outdoor', 'May 12, 2026', '6 min read', 'https://images.unsplash.com/photo-1491557345352-5929e343eb89?auto=format&fit=crop&w=1200&q=80', 1, NULL, 'Toufiq Motion', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=300&q=80', 'Founder & Travel Photographer', NULL, '[\"Switzerland\",\"Mountains\",\"Hiking\",\"Weekend\"]', '[\"The morning sun spills gold over snow-capped ridges as crisp alpine air fills your lungs. A weekend in the Swiss Alps is an antidote to the bustling modern world.\",\"From scenic cogwheel trains winding past emerald meadows to fondue dinners under starry mountain skies, every hour spent in these highlands feels elevated and deeply grounding.\"]', 563, 72, 1, '2026-10-30 21:07:30', '2026-10-30 21:07:30', NULL, NULL, NULL, NULL, NULL, 0, NULL, 85, 90, 0, NULL) ON DUPLICATE KEY UPDATE `slug` = VALUES(`slug`), `title` = VALUES(`title`), `excerpt` = VALUES(`excerpt`), `category` = VALUES(`category`), `subcategory` = VALUES(`subcategory`), `date` = VALUES(`date`), `read_time` = VALUES(`read_time`), `image` = VALUES(`image`), `featured` = VALUES(`featured`), `trending_rank` = VALUES(`trending_rank`), `author_name` = VALUES(`author_name`), `author_avatar` = VALUES(`author_avatar`), `author_role` = VALUES(`author_role`), `quote` = VALUES(`quote`), `tags_json` = VALUES(`tags_json`), `content_json` = VALUES(`content_json`), `views_count` = VALUES(`views_count`), `likes_count` = VALUES(`likes_count`), `published` = VALUES(`published`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`), `html_content` = VALUES(`html_content`), `focus_keyword` = VALUES(`focus_keyword`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `canonical_url` = VALUES(`canonical_url`), `no_index` = VALUES(`no_index`), `og_image` = VALUES(`og_image`), `seo_score` = VALUES(`seo_score`), `readability_score` = VALUES(`readability_score`), `has_affiliate_links` = VALUES(`has_affiliate_links`), `affiliate_disclosure_custom` = VALUES(`affiliate_disclosure_custom`);
