INSERT INTO `articles` (`id`, `slug`, `title`, `excerpt`, `category`, `subcategory`, `date`, `read_time`, `image`, `featured`, `trending_rank`, `author_name`, `author_avatar`, `author_role`, `quote`, `tags_json`, `content_json`, `views_count`, `likes_count`, `published`, `created_at`, `updated_at`, `html_content`, `focus_keyword`, `meta_title`, `meta_description`, `canonical_url`, `no_index`, `og_image`, `seo_score`, `readability_score`, `has_affiliate_links`, `affiliate_disclosure_custom`) VALUES ('ten-simple-habits-healthier-life', '10-simple-habits-for-a-happier-healthier-life', '10 Simple Habits for a Happier, Healthier Life', 'Small changes can make a big difference. Discover 10 easy habits to help you feel more energetic, positive and balanced every day.', 'Health & Wellbeing', 'Healthy Living', 'May 15, 2026', '8 min read', 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=1200&q=80', 1, NULL, 'Maya Lin', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=300&q=80', 'Wellness & Mindfulness Editor', 'True health is not an obsession with perfection; it is a gentle kindness you grant your body and spirit each morning.', '[\"Wellness\",\"Health\",\"Habits\",\"Nutrition\",\"Mindfulness\"]', '[\"We often assume wellness requires punishing workout regimes and radical life overhauls. Yet clinical psychology and longevity research reveal that lasting vigor is built on micro-consistency.\",\"Habit 1: Morning Light Exposure. Getting 10-15 minutes of natural sunlight in your eyes within an hour of waking resets your circadian rhythm and boosts daytime dopamine.\",\"Habit 2: Mindful Hydration. Drink 500ml of room temperature water with a pinch of mineral salt before your first cup of coffee.\",\"Habit 3: The 20-Minute Movement Rule. A brisk outdoor walk after meals blunts glucose spikes and stimulates cerebral blood flow.\"]', 435, 73, 1, '2026-10-30 21:07:30', '2026-10-30 21:07:30', NULL, NULL, NULL, NULL, NULL, 0, NULL, 85, 90, 0, NULL) ON DUPLICATE KEY UPDATE `slug` = VALUES(`slug`), `title` = VALUES(`title`), `excerpt` = VALUES(`excerpt`), `category` = VALUES(`category`), `subcategory` = VALUES(`subcategory`), `date` = VALUES(`date`), `read_time` = VALUES(`read_time`), `image` = VALUES(`image`), `featured` = VALUES(`featured`), `trending_rank` = VALUES(`trending_rank`), `author_name` = VALUES(`author_name`), `author_avatar` = VALUES(`author_avatar`), `author_role` = VALUES(`author_role`), `quote` = VALUES(`quote`), `tags_json` = VALUES(`tags_json`), `content_json` = VALUES(`content_json`), `views_count` = VALUES(`views_count`), `likes_count` = VALUES(`likes_count`), `published` = VALUES(`published`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`), `html_content` = VALUES(`html_content`), `focus_keyword` = VALUES(`focus_keyword`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `canonical_url` = VALUES(`canonical_url`), `no_index` = VALUES(`no_index`), `og_image` = VALUES(`og_image`), `seo_score` = VALUES(`seo_score`), `readability_score` = VALUES(`readability_score`), `has_affiliate_links` = VALUES(`has_affiliate_links`), `affiliate_disclosure_custom` = VALUES(`affiliate_disclosure_custom`);
