-- Table `pages`: 3 rows
INSERT INTO `pages` (`id`, `title`, `slug`, `excerpt`, `status`, `featured_image`, `template`, `blocks_json`, `meta_title`, `meta_description`, `focus_keyword`, `canonical_url`, `no_index`, `seo_score`, `is_system`, `views`, `created_at`, `updated_at`) VALUES ('page-destinations', 'Destinations & Slow Escapes 2026', 'destinations-2026', 'A curated visual index of mindful travel itineraries, secluded coastal villages, and alpine retreats around the globe.', 'published', 'https://images.unsplash.com/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80', 'custom', '[{\"id\":\"blk-hero-1\",\"type\":\"hero\",\"data\":{\"title\":\"Destinations & Slow Escapes 2026\",\"subtitle\":\"A curated visual index of mindful travel itineraries, secluded coastal villages, and alpine retreats around the globe.\",\"badgeText\":\"Curated Editorial Issue\",\"bgImage\":\"https://images.unsplash.com/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1920&q=80\",\"overlayOpacity\":45,\"align\":\"center\",\"ctaText\":\"Explore Itineraries\",\"ctaLink\":\"#itineraries\",\"secondaryCtaText\":\"View Gallery\",\"secondaryCtaLink\":\"#gallery\"}},{\"id\":\"blk-split-1\",\"type\":\"split_feature\",\"data\":{\"badge\":\"Slow Travel Philosophy\",\"heading\":\"Intentional journeys over rushed bucket lists\",\"description\":\"We believe travel should be an exercise in presence rather than consumption. By staying longer in fewer places, you discover the cadence of village mornings, the aroma of neighborhood bakeries, and the warmth of conversations that never happen on a whirlwind tour.\",\"image\":\"https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1200&q=80\",\"imagePosition\":\"right\",\"bullets\":[\"Locally owned boutique stays & heritage guesthouses\",\"Sunrise photography itineraries without the tourist crowds\",\"Farm-to-table culinary notes and slow coffee roasters\",\"Detailed seasonal packing lists and rail travel routes\"],\"ctaText\":\"Read Our Travel Philosophy\",\"ctaLink\":\"/about\"}},{\"id\":\"blk-cards-1\",\"type\":\"cards_grid\",\"data\":{\"heading\":\"2026 Destination Focus Areas\",\"subtitle\":\"Four distinct geographical landscapes chosen for their natural stillness and cultural depth.\",\"columns\":4,\"cards\":[{\"icon\":\"Compass\",\"title\":\"Cycladic Coastlines\",\"description\":\"Whitewashed archipelagos, hidden swimming coves, and windswept clifftop chapels in Greece.\",\"link\":\"/travel\"},{\"icon\":\"Coffee\",\"title\":\"Nordic Forest Cabins\",\"description\":\"Warm saunas, crackling birchwood fires, and berry picking under the endless Scandinavian twilight.\",\"link\":\"/travel\"},{\"icon\":\"Home\",\"title\":\"Kyoto Machiya Living\",\"description\":\"Centuries-old wooden townhouses, private moss gardens, and traditional morning matcha rituals.\",\"link\":\"/travel\"},{\"icon\":\"Heart\",\"title\":\"Alpine Sanctuary Trails\",\"description\":\"High-elevation glacial lakes, wildflower meadows, and crisp mountain air across Switzerland and Italy.\",\"link\":\"/travel\"}]}},{\"id\":\"blk-faq-1\",\"type\":\"faq_accordion\",\"data\":{\"heading\":\"Planning Your 2026 Journey\",\"subtitle\":\"Frequently asked travel questions regarding logistics, seasons, and packing.\",\"items\":[{\"question\":\"When is the best time of year to visit the Mediterranean without crowds?\",\"answer\":\"We recommend the shoulder seasons: mid-May to early June, or mid-September through October. Temperatures remain warm, waters are swimmable, and villages return to their tranquil local rhythm.\"},{\"question\":\"How do you choose hotels and accommodations featured on Toufiq Motion?\",\"answer\":\"Every property featured has been independently vetted for aesthetic intentionality, high architectural standards, mindful hospitality, and respect for local surroundings.\"},{\"question\":\"What camera gear is recommended for traveling light?\",\"answer\":\"A single mirrorless body paired with a fast 35mm or 50mm prime lens offers the highest optical fidelity while remaining unobtrusive and featherweight on long walking days.\"}]}},{\"id\":\"blk-cta-1\",\"type\":\"cta_banner\",\"data\":{\"tag\":\"Weekly Dispatches\",\"heading\":\"Receive our unreleased travel notes directly in your inbox\",\"description\":\"Every Sunday morning, we send one concise dispatch featuring secret routes, hotel discoveries, and contemplative photography.\",\"buttonText\":\"Join 4,200+ Readers\",\"buttonLink\":\"#newsletter\",\"variant\":\"warm-terracotta\"}}]', 'Destinations & Slow Escapes 2026 — Toufiq Motion Editorial', 'Discover curated slow travel itineraries, coastal sanctuaries, and alpine mountain retreats for 2026 with high-res photography.', 'destinations 2026', 'https://toufiqmotion.com/destinations-2026', 0, 94, 0, 343, '2026-11-08 20:43:01', '2026-11-08 20:43:01') ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `excerpt` = VALUES(`excerpt`), `status` = VALUES(`status`), `featured_image` = VALUES(`featured_image`), `template` = VALUES(`template`), `blocks_json` = VALUES(`blocks_json`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `focus_keyword` = VALUES(`focus_keyword`), `canonical_url` = VALUES(`canonical_url`), `no_index` = VALUES(`no_index`), `seo_score` = VALUES(`seo_score`), `is_system` = VALUES(`is_system`), `views` = VALUES(`views`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `pages` (`id`, `title`, `slug`, `excerpt`, `status`, `featured_image`, `template`, `blocks_json`, `meta_title`, `meta_description`, `focus_keyword`, `canonical_url`, `no_index`, `seo_score`, `is_system`, `views`, `created_at`, `updated_at`) VALUES ('page-partnerships', 'Brand Partnerships & Media Kit', 'partnerships', 'Connecting intentional luxury hospitality and sustainable lifestyle brands with an engaged global audience of cultural travelers.', 'published', 'https://images.unsplash.com/photo-1517842645767-c639042777db?auto=format&fit=crop&w=1200&q=80', 'custom', '[{\"id\":\"blk-hero-2\",\"type\":\"hero\",\"data\":{\"title\":\"Brand Partnerships & Media Kit\",\"subtitle\":\"Connecting intentional luxury hospitality, sustainable lifestyle brands, and design creators with an engaged global audience of cultural travelers.\",\"badgeText\":\"Media Kit 2026\",\"bgImage\":\"https://images.unsplash.com/photo-1517842645767-c639042777db?auto=format&fit=crop&w=1920&q=80\",\"overlayOpacity\":50,\"align\":\"center\",\"ctaText\":\"Download Media Kit (PDF)\",\"ctaLink\":\"#download\",\"secondaryCtaText\":\"Contact Our Team\",\"secondaryCtaLink\":\"/work\"}},{\"id\":\"blk-cards-2\",\"type\":\"cards_grid\",\"data\":{\"heading\":\"Audience Demographics & Reach\",\"subtitle\":\"Our readers are discerning travelers, architects, creators, and professionals with high appreciation for fine aesthetics.\",\"columns\":3,\"cards\":[{\"icon\":\"Compass\",\"title\":\"62,000+ Monthly Readers\",\"description\":\"Global reach centered across North America (42%), Western Europe (36%), and Asia-Pacific (18%).\"},{\"icon\":\"Heart\",\"title\":\"4,200+ Email Subscribers\",\"description\":\"Industry-leading 54.2% average open rate with high click-through engagement on curated dispatches.\"},{\"icon\":\"Sparkles\",\"title\":\"High Editorial Trust\",\"description\":\"98% of our community states they have visited a destination or purchased an item based on Toufiq Motion features.\"}]}},{\"id\":\"blk-split-2\",\"type\":\"split_feature\",\"data\":{\"badge\":\"Partnership Formats\",\"heading\":\"Bespoke storytelling tailored to your brand identity\",\"description\":\"We do not run generic banner advertisements. Instead, we co-create bespoke editorial stories, cinematography, and atmospheric visual campaigns that highlight your brand heritage with grace and dignity.\",\"image\":\"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80\",\"imagePosition\":\"left\",\"bullets\":[\"Cornerstone destination features with high organic Google SERP ranking\",\"Full commercial licensing for our 4K cinematic footage & RAW photography\",\"Dedicated sponsored newsletter takeovers with zero clutter\",\"Experiential press trips & seasonal launch activations\"],\"ctaText\":\"Start a Conversation\",\"ctaLink\":\"/work\"}},{\"id\":\"blk-quote-2\",\"type\":\"quote\",\"data\":{\"quote\":\"Toufiq Motion captured the understated soul of our boutique property like no one else. The resulting photography and editorial guide drove an immediate surge in direct bookings from high-value international guests.\",\"author\":\"Elena Vance\",\"role\":\"Creative Director, Villa Kalon Capri\",\"avatar\":\"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=200&q=80\"}},{\"id\":\"blk-cta-2\",\"type\":\"cta_banner\",\"data\":{\"tag\":\"Get in Touch\",\"heading\":\"Ready to create something memorable together?\",\"description\":\"Send us a brief overview of your brand or property, and our editorial director will respond within 24 hours.\",\"buttonText\":\"Submit Partnership Inquiry\",\"buttonLink\":\"/work\",\"variant\":\"dark-charcoal\"}}]', 'Brand Partnerships & Media Kit 2026 — Toufiq Motion', 'Work with Toufiq Motion on luxury hospitality storytelling, bespoke photography campaigns, and cultural destination features.', 'media kit partnerships', 'https://toufiqmotion.com/partnerships', 0, 96, 0, 189, '2026-11-08 20:43:01', '2026-11-08 20:43:01') ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `excerpt` = VALUES(`excerpt`), `status` = VALUES(`status`), `featured_image` = VALUES(`featured_image`), `template` = VALUES(`template`), `blocks_json` = VALUES(`blocks_json`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `focus_keyword` = VALUES(`focus_keyword`), `canonical_url` = VALUES(`canonical_url`), `no_index` = VALUES(`no_index`), `seo_score` = VALUES(`seo_score`), `is_system` = VALUES(`is_system`), `views` = VALUES(`views`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `pages` (`id`, `title`, `slug`, `excerpt`, `status`, `featured_image`, `template`, `blocks_json`, `meta_title`, `meta_description`, `focus_keyword`, `canonical_url`, `no_index`, `seo_score`, `is_system`, `views`, `created_at`, `updated_at`) VALUES ('page-faq', 'Frequently Asked Questions', 'faq', 'Transparency regarding our editorial standards, gear recommendations, print sales, and community guidelines.', 'published', 'https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1200&q=80', 'custom', '[{\"id\":\"blk-hero-3\",\"type\":\"hero\",\"data\":{\"title\":\"Frequently Asked Questions & Standards\",\"subtitle\":\"Transparency regarding our editorial standards, gear recommendations, print sales, and community guidelines.\",\"badgeText\":\"Help & Knowledge Center\",\"bgImage\":\"https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1920&q=80\",\"overlayOpacity\":40,\"align\":\"center\",\"ctaText\":\"Browse Topics\",\"ctaLink\":\"#faq-content\"}},{\"id\":\"blk-faq-3\",\"type\":\"faq_accordion\",\"data\":{\"heading\":\"Editorial & Photography Questions\",\"subtitle\":\"Clear answers to common questions about our journal.\",\"items\":[{\"question\":\"Do you accept guest contributions or freelance pitches?\",\"answer\":\"Yes! We periodically accept original essays and photo-essays exploring mindful travel, culinary craft, and slow lifestyle. Writers can submit pitches via our Work With Us contact portal.\"},{\"question\":\"How do you disclose sponsored content or affiliate links?\",\"answer\":\"Full transparency is fundamental to our ethics. Any partnered stay or sponsored feature is explicitly flagged with an editorial badge at the top of the article. We never accept payment in exchange for positive reviews.\"},{\"question\":\"Can I purchase prints of photographs featured on the website?\",\"answer\":\"Archival museum-quality giclée prints are released in limited seasonal editions. Join our newsletter to receive early collector access before public releases.\"},{\"question\":\"What cameras, lenses, and drone do you use?\",\"answer\":\"We primarily shoot on full-frame Sony mirrorless systems paired with G-Master prime lenses (35mm f/1.4 and 50mm f/1.2), along with DJI Mavic 3 Cine for aerial landscapes.\"}]}},{\"id\":\"blk-cta-3\",\"type\":\"cta_banner\",\"data\":{\"tag\":\"Need Assistance?\",\"heading\":\"Have a specific inquiry not covered here?\",\"description\":\"Our team is always happy to hear from fellow travelers, readers, and creatives.\",\"buttonText\":\"Contact Us Directly\",\"buttonLink\":\"/contact\",\"variant\":\"warm-terracotta\"}}]', 'Frequently Asked Questions — Toufiq Motion', 'Read answers to common questions regarding Toufiq Motion editorial dispatches, photography gear, and partnership guidelines.', 'faq editorial standards', 'https://toufiqmotion.com/faq', 0, 91, 0, 126, '2026-11-08 20:43:01', '2026-11-08 20:43:01') ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `excerpt` = VALUES(`excerpt`), `status` = VALUES(`status`), `featured_image` = VALUES(`featured_image`), `template` = VALUES(`template`), `blocks_json` = VALUES(`blocks_json`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `focus_keyword` = VALUES(`focus_keyword`), `canonical_url` = VALUES(`canonical_url`), `no_index` = VALUES(`no_index`), `seo_score` = VALUES(`seo_score`), `is_system` = VALUES(`is_system`), `views` = VALUES(`views`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);

